"""Surface pick marker + consistent Model Atelier menu readability and grouping."""
import hashlib
import json

MARKER_JS = "// §E 11.104: an actual viewport point indicator, not just numerical inputs.\n// Non-pickable helper geometry; no influence on the source mesh or exported data.\nlet atelierSculptPickIndicator=null;\nlet atelierSculptPickLabel=null;\nfunction atelierSculptPickMarkerInstall(){\n const pick=$m('SculptBrushPick');\n if(!pick||document.getElementById('modelAtelierSculptPickedReadout'))return;\n const output=document.createElement('output');\n output.id='modelAtelierSculptPickedReadout';\n output.className='atelier-sculpt-picked-readout';\n output.setAttribute('role','status');\n output.setAttribute('aria-live','polite');\n output.hidden=true;\n const actions=pick.closest('.atelier-inspector-actions');\n if(actions)actions.insertAdjacentElement('afterend',output);\n atelierSculptPickLabel=output;\n}\nfunction atelierSculptPickMarkerClear(){\n if(!atelierSculptPickIndicator)return;\n const helper=atelierSculptPickIndicator;\n helper.parent?.remove(helper);\n helper.traverse(o=>{\n  o.geometry?.dispose?.();\n  const materials=Array.isArray(o.material)?o.material:(o.material?[o.material]:[]);\n  for(const material of materials)material?.dispose?.();\n });\n atelierSculptPickIndicator=null;\n}\nfunction atelierSculptPickMarkerRefresh(){\n atelierSculptPickMarkerClear();\n if(!atelierSculptPickLabel)atelierSculptPickLabel=document.getElementById('modelAtelierSculptPickedReadout');\n const hit=atelierSculptHit;\n if(atelierSculptPickLabel)atelierSculptPickLabel.hidden=!hit;\n if(!hit||!modelRoot||!world)return;\n const mesh=modelRoot.children.find(o=>o.isMesh&&o.userData.atelierId===hit.partId);\n if(!mesh)return;\n mesh.updateMatrixWorld(true);\n const local=new THREE.Vector3(...hit.center);\n const worldPoint=mesh.localToWorld(local.clone());\n const localNormal=new THREE.Vector3(...hit.axis).normalize();\n const worldNormal=localNormal.clone().applyMatrix3(\n   new THREE.Matrix3().getNormalMatrix(mesh.matrixWorld)).normalize();\n const radius=.055;\n const helper=new THREE.Group();\n helper.name='Picked sculpt center indicator (editor only)';\n helper.userData.atelierHelper=true;\n helper.position.copy(worldPoint);\n helper.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),worldNormal);\n const ring=new THREE.Mesh(\n   new THREE.TorusGeometry(radius,.0055,7,40),\n   new THREE.MeshBasicMaterial({color:0xffdf65,depthTest:false,depthWrite:false,transparent:true,opacity:.98})\n );\n ring.renderOrder=990;ring.position.z=.007;helper.add(ring);\n const crossShape=new THREE.BufferGeometry().setFromPoints([\n   new THREE.Vector3(-radius*.38,0,.01),new THREE.Vector3(radius*.38,0,.01),\n   new THREE.Vector3(0,-radius*.38,.01),new THREE.Vector3(0,radius*.38,.01)\n ]);\n const cross=new THREE.LineSegments(crossShape,new THREE.LineBasicMaterial({\n   color:0xffffff,depthTest:false,depthWrite:false\n }));\n cross.renderOrder=991;helper.add(cross);\n const arrow=new THREE.ArrowHelper(new THREE.Vector3(0,0,1),new THREE.Vector3(0,0,.012),\n   radius*2,0x61f2e6,radius*.48,radius*.25);\n arrow.traverse(o=>{\n  if(o.material){o.material.depthTest=false;o.material.depthWrite=false;}\n  o.renderOrder=992;\n });helper.add(arrow);\n world.add(helper);atelierSculptPickIndicator=helper;\n if(atelierSculptPickLabel){\n  const xyz=hit.center.map(v=>Number(v).toFixed(3)).join(', ');\n  atelierSculptPickLabel.textContent='● Picked surface: ('+xyz+') · yellow ring = center · cyan arrow = outward normal';\n }\n}\n"
CSS = "\n/* §E v11.104: coherent typography/layout across native floating tool menus.\n   Presentation only. Keep v11.103 inspector width/height, dock position and drag. */\n.model-atelier .atelier-inspector,\n.model-atelier .atelier-context-workbench{\n color:#eff7ff;\n font-family:system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n}\n.model-atelier .atelier-inspector :is(h3,h4),\n.model-atelier .atelier-context-workbench :is(h3,h4){\n color:#f2fbff!important;\n font-size:15px!important;\n line-height:1.4!important;\n font-weight:750!important;\n letter-spacing:.01em;\n margin:3px 0 7px!important;\n}\n.model-atelier .atelier-inspector :is(fieldset),\n.model-atelier .atelier-context-workbench :is(fieldset){\n min-width:0!important;\n max-width:100%;\n border:1px solid #486883!important;\n border-radius:10px!important;\n background:#172a42!important;\n padding:12px!important;\n margin:8px 0!important;\n}\n.model-atelier .atelier-inspector legend,\n.model-atelier .atelier-context-workbench legend{\n color:#a4e7ee!important;\n font-size:14px!important;\n font-weight:750!important;\n line-height:1.45!important;\n padding:0 6px!important;\n white-space:normal;\n}\n.model-atelier .atelier-inspector :is(label),\n.model-atelier .atelier-context-workbench :is(label){\n color:#d9eafb!important;\n font-size:13.5px!important;\n font-weight:550!important;\n line-height:1.45!important;\n gap:6px!important;\n min-width:0!important;\n overflow-wrap:anywhere;\n}\n.model-atelier .atelier-inspector :is(p,small),\n.model-atelier .atelier-context-workbench :is(p,small){\n color:#afc6dc!important;\n font-size:12.5px!important;\n line-height:1.5!important;\n margin:5px 0!important;\n overflow-wrap:anywhere;\n}\n.model-atelier .atelier-inspector :is(.atelier-pair,.atelier-transform),\n.model-atelier .atelier-context-workbench :is(.atelier-pair,.atelier-transform){\n gap:10px!important;\n min-width:0!important;\n align-items:start;\n}\n.model-atelier .atelier-inspector :is(input:not([type=checkbox]):not([type=radio]):not([type=color]):not([type=range]):not([type=file]),select,textarea),\n.model-atelier .atelier-context-workbench :is(input:not([type=checkbox]):not([type=radio]):not([type=color]):not([type=range]):not([type=file]),select,textarea){\n box-sizing:border-box;\n min-width:0!important;\n max-width:100%!important;\n width:100%;\n min-height:42px!important;\n padding:9px 10px!important;\n font-size:16px!important;\n line-height:1.4!important;\n color:#f4fcff!important;\n background:#203550!important;\n border:1px solid #63839f!important;\n border-radius:8px!important;\n}\n.model-atelier .atelier-inspector :is(input,select,textarea):focus-visible,\n.model-atelier .atelier-context-workbench :is(input,select,textarea):focus-visible{\n outline:2px solid #8bf3e3!important;\n outline-offset:1px!important;\n}\n.model-atelier .atelier-inspector :is(input[type=checkbox],input[type=radio]),\n.model-atelier .atelier-context-workbench :is(input[type=checkbox],input[type=radio]){\n width:20px!important;height:20px!important;\n min-height:20px!important;flex:0 0 20px!important;\n margin:0 6px 0 0!important;\n accent-color:#70dbd6;\n}\n.model-atelier .atelier-inspector label:has(>input[type=checkbox]),\n.model-atelier .atelier-context-workbench label:has(>input[type=checkbox]){\n display:flex!important;flex-direction:row!important;\n align-items:center!important;gap:9px!important;\n padding:9px!important;border:1px solid #405c79;border-radius:8px;\n background:#1e304a;\n}\n.model-atelier .atelier-inspector .atelier-inspector-actions,\n.model-atelier .atelier-inspector .atelier-sculpt-actions{\n display:grid!important;\n grid-template-columns:repeat(2,minmax(0,1fr))!important;\n gap:8px!important;\n margin:8px 0!important;\n}\n.model-atelier .atelier-inspector .atelier-inspector-actions button,\n.model-atelier .atelier-inspector .atelier-sculpt-actions button,\n.model-atelier .atelier-context-workbench button{\n min-width:0!important;\n min-height:44px!important;\n padding:9px 8px!important;\n font-size:13px!important;\n font-weight:680!important;\n line-height:1.35!important;\n white-space:normal!important;\n overflow-wrap:break-word;\n background:#2b4364;\n border:1px solid #6d8cad!important;\n border-radius:8px!important;\n}\n.model-atelier .atelier-inspector .atelier-inspector-actions button:hover,\n.model-atelier .atelier-inspector .atelier-inspector-actions button:focus-visible{\n background:#335778;\n}\n.model-atelier #modelAtelierSculptBrushPick,\n.model-atelier #modelAtelierSculptBrushApply{\n background:#176e79!important;\n border-color:#70dcd6!important;\n color:#fff!important;\n}\n.model-atelier #modelAtelierSculptBrushUndoStroke{\n background:#3b3d5d!important;\n}\n.model-atelier #modelAtelierSculptBrush{\n padding:12px!important;\n gap:10px!important;\n background:#15263d!important;\n border:1px solid #4a6d87!important;\n border-radius:11px!important;\n}\n.model-atelier #modelAtelierSculptBrush >p{\n padding:8px 10px!important;\n background:#1e3048;\n border-left:3px solid #69cbd0;\n border-radius:5px;\n}\n.model-atelier .atelier-sculpt-picked-readout:not([hidden]){\n display:block!important;\n margin:8px 0 12px!important;\n padding:10px 12px!important;\n font:650 13px/1.5 system-ui,sans-serif!important;\n color:#ffedb5!important;\n border:1px solid #a99649!important;\n background:#393426!important;\n border-radius:9px;\n white-space:normal!important;\n overflow-wrap:anywhere;\n}\n.model-atelier .atelier-inspector :is(.atelier-import,.atelier-disclaimer){\n font-size:12.5px!important;\n line-height:1.5!important;\n}\n@media(max-width:980px),(pointer:coarse){\n .model-atelier .atelier-inspector,\n .model-atelier .atelier-context-workbench{\n  scrollbar-width:thin;\n  scrollbar-color:#72acbe #1b3047;\n }\n .model-atelier .atelier-inspector :is(fieldset),\n .model-atelier #modelAtelierSculptBrush{padding:11px!important}\n .model-atelier .atelier-inspector :is(.atelier-pair,.atelier-transform){gap:8px!important}\n .model-atelier .atelier-inspector .atelier-tool-handle :is(button){\n  min-height:38px!important;padding:5px 7px!important;\n  font-size:12px!important;white-space:nowrap!important;\n }\n}\n"

def once(html,a,b):
    n=html.count(a)
    assert n==1,(a[:100],n)
    return html.replace(a,b,1)

def apply(html):
    html=once(html,'let atelierSculptArmed=false,atelierSculptHit=null;',
         MARKER_JS+'\nlet atelierSculptArmed=false,atelierSculptHit=null;')
    html=once(html,' if(atelierSculptHit?.partId!==selection)atelierSculptHit=null;\n if(!p)atelierSculptArmed=false;',
              ' if(atelierSculptHit?.partId!==selection)atelierSculptHit=null;\n if(!p)atelierSculptArmed=false;\n atelierSculptPickMarkerRefresh();')
    html=once(html,"function atelierSculptInstall(){\n $m('SculptBrushPick').addEventListener('click',()=>{",
              "function atelierSculptInstall(){\n atelierSculptPickMarkerInstall();\n $m('SculptBrushPick').addEventListener('click',()=>{")
    assert '</head>' in html
    html=html.replace('</head>','<style id="se-v11104-clean-menus">'+CSS+'</style>\n</head>',1)
    html=once(html,'SWYRL_ENGINE_DEPLOY_MARKER: V11_103_DOUBLE_INSPECTOR_HEIGHT',
                   'SWYRL_ENGINE_DEPLOY_MARKER: V11_104_PICK_MARKER_READABLE_MENUS')
    for a,b in [
      ('ENGINE · MAKER v11.103','ENGINE · MAKER v11.104'),
      ('v11.103 · taller draggable mobile tools','v11.104 · visible picks and readable tool menus'),
      ("window.SWRLZ_FORGE_BUILD={version:'v11.103'","window.SWRLZ_FORGE_BUILD={version:'v11.104'"),
      ('<title>§wyrl§ Engine · Maker v11.103</title>','<title>§wyrl§ Engine · Maker v11.104</title>'),
    ]:html=once(html,a,b)
    p='const SE_RELEASE_NOTES='
    at=html.index(p)+len(p)
    notes,n=json.JSONDecoder().raw_decode(html[at:])
    notes.update(title='Visible sculpt pick and readable editor menus',
      date='2026-10-24',changes=[
       'Draw a yellow picked-position ring, white crosshair and cyan surface-normal arrow atop the selected mesh, including in X-Ray view, with a numeric readout.',
       'Use clear menu sections, legible labels and help text, aligned forms and accessible mobile action buttons without changing existing tool behavior.',
       'Preserve v11.103 window width, height, drag handling, touch scrolling gutters, press-and-hold number keypad and all existing model data.'
    ])
    html=html[:at]+json.dumps(notes,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')+html[at+n:]
    b=html.encode('utf8')
    print('SWRLZ_V11104_BUILD_MEASURE',len(b),hashlib.sha256(b).hexdigest(),flush=True)
    return html
